import { Injectable, TemplateRef } from '@angular/core';
import { BehaviorSubject, Observable } from 'rxjs';

@Injectable()
export class AdminHeaderService {

	private templateSubject: BehaviorSubject<TemplateRef<any> | null> = new BehaviorSubject<TemplateRef<any> | null>(null);
	private _template: Observable<TemplateRef<any> | null> = this.templateSubject.asObservable();

	public get template(): Observable<TemplateRef<any> | null> {
		return this._template;
	}
	public setHeaderTemplate(templateRef: TemplateRef<any> | null): void {
		this.templateSubject.next(templateRef);
	}
}